function swapAdjectives(sentence) {
  // 1. Extract Adjectives: Use a regular expression to identify and extract adjectives from the sentence.  A robust approach involves capturing patterns like  adjective-noun phrases while handling potential complexities (e.g., multiple adjectives, participles). Here's a foundational regex for demonstration, refine it for greater accuracy in real-world scenarios:
  const regex = /(?<=\b)\w+(?:\s+[\w\-]+)*\b(?!\s*[\W])/g; // Matches word sequences likely to be adjectives
  const adjectives = sentence.match(regex);

  // 2. Reorder and Reconstruct:
  if (adjectives.length > 1) {  // Ensure at least two adjectives exist for swapping
    const reorderedAdjectives = [adjectives[1], adjectives[0]]; // Swap the first two
    const newSentence = sentence.replace(new RegExp(`(${adjectives[0]}|${adjectives[1]})`, 'g'), 
                                        (match) => reorderedAdjectives.includes(match) ? reorderedAdjectives.shift() : match);
    return newSentence;
  } else {
    return sentence; // No meaningful swap if fewer than two adjectives
  }
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjectives(originalSentence);
console.log(swappedSentence); // Output: Green beautiful trees are in the park 
```

