async function postToSlack(text, channelId, slackToken) {
  // **Helpfulness (High):** Clearly structured function with comments explaining each step.
  try {
    const response = await fetch(`https://slack.com/api/chat.postMessage`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${slackToken}` // Essential for API authentication
      },
      body: JSON.stringify({
        channel: channelId,  // Target Slack channel ID
        text: text,          // Input text to be posted
        // Optional: Add more formatting/payload elements here for richer messages (e.g., blocks, attachments)
      })
    });

    const data = await response.json();
    if (response.ok) { // **Verbosity (Medium):** Check for successful API response
      console.log(`Message posted successfully to channel ${channelId}:`, data.message.text); 
      return data; // Return success data for clarity
    } else {
      console.error(`Error posting to Slack: ${data.error}`, data); 
      throw new Error(`Slack API Error: ${data.error}`); // Robust error handling
    }
  } catch (error) {
    console.error("An unexpected error occurred during Slack posting:", error);
    throw error; // Re-throw for caller handling
  }
}
```

