#include <iostream>
#include <vector>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
vector<int> fibonacciSequence(int start1, int start2, int count) {
    vector<int> seq{start1, start2}; // Initialize with given starting values
    if (count <= 2) {  // Base case: Handle cases with <= 2 elements
        return seq;
    }

    for (int i = 2; i < count; ++i) {
        int nextFib = seq[i - 1] + seq[i - 2];
        seq.push_back(nextFib);
    }
    return seq;
}

// Input validation function
bool validateInput(int& num, const string& prompt) {
    while (!(cin >> num) || num < 0) {
        cin.clear();  // Reset error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Clear input buffer
        cerr << "Invalid input for " << prompt << ". Please enter a non-negative integer: ";
    }
    return true;
}

int main() {
    int start1, start2, sequenceLength;

    cout << "Enter the first two integers for the Fibonacci sequence: ";
    validateInput(start1, "the first integer");
    validateInput(start2, "the second integer");

    cout << "Enter the desired length of the sequence: ";
    validateInput(sequenceLength, "sequence length");

    vector<int> fibSeq = fibonacciSequence(start1, start2, sequenceLength);

    cout << "Generated Fibonacci sequence: ";
    for (size_t i = 0; i < fibSeq.size(); ++i) {
        cout << fibSeq[i];
        if (i < fibSeq.size() - 1) {
            cout << ", "; // Separator between elements
        }
    }
    cout << endl;

    return 0;
}
```

