    ]

    for (factor, descriptions) in factors {
        let skiingDesc = userChoice == "skiing" ? descriptions[0].0 : descriptions[1].0 // Prioritize skiing's description
        let snowboardingDesc = userChoice == "snowboarding" ? descriptions[0].0 : descriptions[1].0 // Prioritize snowboarding's

        comparisonData.append([factor, skiingDesc, snowboardingDesc])
    }

    return comparisonData
}

